query:
fragment leagueWithScheduleFrag on League {
  id
  name
  slug
  schedule(offset: $offset, limit: $limit) {
    ... on Tournament {
      id
      name
      startTime
      hostLocation {
        id
        address {
          id
          name
          __typename
        }
        __typename
      }
      __typename
    }
    ... on OtherEvent {
      id
      name
      startTime
      address {
        id
        name
        latitude
        longitude
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

query leagueEvents($offset: Int!, $limit: Int!) {
  league(id: 589) {
    ...leagueWithScheduleFrag
    __typename
  }
  viewer {
    id
    ... on Member {
      leagues(current: true) {
        ...leagueWithScheduleFrag
        __typename
      }
      __typename
    }
    ... on ExternalStaff {
      leagues {
        ...leagueWithScheduleFrag
        __typename
      }
      __typename
    }
    __typename
  }
}
